#include <iostream>
#include <algorithm>
using namespace std;

long long gcd_of(long long a, long long b) {
    while (b != 0) {
        long long temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

struct Fraction {
    long long numerator, denominator;
    Fraction() : numerator(0), denominator(1) {}
    Fraction(long long n, long long d) : numerator(n), denominator(d) {}
    void reduce_fraction() {
        long long g = gcd_of(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }
    bool is_less(const Fraction& other) const {
        return numerator * other.denominator < other.numerator * denominator;
    }
    void display() const {
        cout << numerator << "/" << denominator;
    }
};

int main() {
    long long x, y, total;
    cin >> x >> y >> total;
    Fraction limit(50, 1);
    Fraction base(x, y);
    long long min_r = 0, min_i = 1;
    for (long long i = 1; i <= total; ++i) {
        long long r = (base.numerator * i) / base.denominator;
        long long z = (base.numerator * i) % base.denominator;
        if (z > base.denominator / 2) {
            r++;
            z = base.denominator - z;
        }
        Fraction current(z, i * base.denominator);
        if (current.is_less(limit)) {
            limit = current;
            min_r = r;
            min_i = i;
        }
    }
    cout << min_r;
}
